-- ENTREGA 2 | ÓTICA KADOSH | MySQL 8.0.16+
-- Modelo revisado a partir do levantamento documentado na Entrega 1.
-- MASSA INTEIRAMENTE FICTÍCIA. Valores, datas e pessoas do INSERT são simulados.
-- Execução: MySQL Workbench, conexão a servidor MySQL 8, banco novo.
CREATE DATABASE IF NOT EXISTS otica_kadosh_e2 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE otica_kadosh_e2;

CREATE TABLE cliente (
 id_cliente INT PRIMARY KEY, nome VARCHAR(120) NOT NULL,
 telefone VARCHAR(20), email VARCHAR(150), bairro VARCHAR(100), cep CHAR(8),
 ativo BOOLEAN NOT NULL DEFAULT TRUE
) ENGINE=InnoDB;
CREATE TABLE funcionario (
 id_funcionario INT PRIMARY KEY, nome VARCHAR(120) NOT NULL,
 funcao VARCHAR(70) NOT NULL, ativo BOOLEAN NOT NULL DEFAULT TRUE
) ENGINE=InnoDB;
CREATE TABLE atendimento (
 id_atendimento INT PRIMARY KEY, id_cliente INT NOT NULL, id_funcionario INT NOT NULL,
 data_atendimento DATE NOT NULL, meio_contato VARCHAR(30) NOT NULL,
 procedimento VARCHAR(25) NOT NULL CHECK (procedimento IN ('RECEITA_EXTERNA','TESTE_NA_OTICA','ORIENTACAO')),
 CONSTRAINT fk_at_cliente FOREIGN KEY (id_cliente) REFERENCES cliente(id_cliente) ON DELETE RESTRICT,
 CONSTRAINT fk_at_func FOREIGN KEY (id_funcionario) REFERENCES funcionario(id_funcionario) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE receita (
 id_receita INT PRIMARY KEY, id_atendimento INT NOT NULL UNIQUE,
 origem VARCHAR(10) NOT NULL CHECK(origem IN ('EXTERNA','INTERNA')),
 data_receita DATE NOT NULL, observacao_laudo VARCHAR(200),
 CONSTRAINT fk_rec_at FOREIGN KEY (id_atendimento) REFERENCES atendimento(id_atendimento) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE medida_receita (
 id_receita INT NOT NULL, olho CHAR(2) NOT NULL CHECK(olho IN ('OD','OE')),
 distancia VARCHAR(5) NOT NULL CHECK(distancia IN ('LONGE','PERTO')),
 esferico DECIMAL(5,2), cilindrico DECIMAL(5,2),
 eixo SMALLINT CHECK(eixo BETWEEN 0 AND 180), dnp DECIMAL(5,2), altura DECIMAL(5,2),
 PRIMARY KEY (id_receita,olho,distancia),
 CONSTRAINT fk_med_rec FOREIGN KEY(id_receita) REFERENCES receita(id_receita) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE fornecedor (
 id_fornecedor INT PRIMARY KEY, nome VARCHAR(120) NOT NULL, telefone VARCHAR(20)
) ENGINE=InnoDB;
CREATE TABLE categoria (
 id_categoria INT PRIMARY KEY, nome VARCHAR(40) NOT NULL UNIQUE
) ENGINE=InnoDB;
CREATE TABLE produto (
 id_produto INT PRIMARY KEY, id_categoria INT NOT NULL,
 sku VARCHAR(35) NOT NULL UNIQUE, descricao VARCHAR(160) NOT NULL,
 preco_referencia DECIMAL(10,2) NOT NULL CHECK(preco_referencia>=0),
 estoque_minimo INT NOT NULL DEFAULT 0 CHECK(estoque_minimo>=0), ativo BOOLEAN NOT NULL DEFAULT TRUE,
 CONSTRAINT fk_prod_categoria FOREIGN KEY(id_categoria) REFERENCES categoria(id_categoria) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE pedido (
 id_pedido INT PRIMARY KEY, id_atendimento INT NOT NULL UNIQUE,
 id_receita INT NOT NULL UNIQUE, data_pedido DATE NOT NULL,
 status VARCHAR(12) NOT NULL CHECK(status IN ('ABERTO','CONCLUIDO','CANCELADO')),
 desconto DECIMAL(10,2) NOT NULL DEFAULT 0 CHECK(desconto>=0),
 observacoes VARCHAR(200),
 CONSTRAINT fk_ped_at FOREIGN KEY(id_atendimento) REFERENCES atendimento(id_atendimento) ON DELETE RESTRICT,
 CONSTRAINT fk_ped_rec FOREIGN KEY(id_receita) REFERENCES receita(id_receita) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE item_pedido (
 id_pedido INT NOT NULL, id_produto INT NOT NULL,
 quantidade INT NOT NULL CHECK(quantidade>0), preco_unitario DECIMAL(10,2) NOT NULL CHECK(preco_unitario>=0),
 PRIMARY KEY(id_pedido,id_produto),
 CONSTRAINT fk_ip_ped FOREIGN KEY(id_pedido) REFERENCES pedido(id_pedido) ON DELETE RESTRICT,
 CONSTRAINT fk_ip_prod FOREIGN KEY(id_produto) REFERENCES produto(id_produto) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE pagamento (
 id_pagamento INT PRIMARY KEY, id_pedido INT NOT NULL, numero_parcela SMALLINT NOT NULL CHECK(numero_parcela>=1),
 forma VARCHAR(12) NOT NULL CHECK(forma IN ('PIX','DINHEIRO','DEBITO','CREDITO')),
 valor DECIMAL(10,2) NOT NULL CHECK(valor>0), vencimento DATE NOT NULL,
 data_pagamento DATE NULL, status VARCHAR(12) NOT NULL CHECK(status IN ('PENDENTE','QUITADO','ESTORNADO')),
 UNIQUE(id_pedido,numero_parcela),
 CONSTRAINT ck_pg_data CHECK((status='QUITADO' AND data_pagamento IS NOT NULL) OR (status IN ('PENDENTE','ESTORNADO'))),
 CONSTRAINT fk_pg_ped FOREIGN KEY(id_pedido) REFERENCES pedido(id_pedido) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE compra (
 id_compra INT PRIMARY KEY, id_pedido INT NOT NULL,
 id_fornecedor INT NOT NULL, id_funcionario INT NOT NULL,
 data_solicitacao DATE NOT NULL, data_chegada DATE,
 status VARCHAR(12) NOT NULL CHECK(status IN ('SOLICITADA','RECEBIDA','CANCELADA')),
 CONSTRAINT ck_compra_datas CHECK(data_chegada IS NULL OR data_chegada>=data_solicitacao),
 CONSTRAINT fk_comp_ped FOREIGN KEY(id_pedido) REFERENCES pedido(id_pedido) ON DELETE RESTRICT,
 CONSTRAINT fk_comp_for FOREIGN KEY(id_fornecedor) REFERENCES fornecedor(id_fornecedor) ON DELETE RESTRICT,
 CONSTRAINT fk_comp_func FOREIGN KEY(id_funcionario) REFERENCES funcionario(id_funcionario) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE item_compra (
 id_compra INT NOT NULL, id_produto INT NOT NULL,
 quantidade INT NOT NULL CHECK(quantidade>0),
 custo_unitario DECIMAL(10,2) NOT NULL CHECK(custo_unitario>=0),
 PRIMARY KEY(id_compra,id_produto),
 CONSTRAINT fk_ic_comp FOREIGN KEY(id_compra) REFERENCES compra(id_compra) ON DELETE RESTRICT,
 CONSTRAINT fk_ic_prod FOREIGN KEY(id_produto) REFERENCES produto(id_produto) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE montagem (
 id_montagem INT PRIMARY KEY, id_pedido INT NOT NULL UNIQUE, id_funcionario INT NOT NULL,
 data_inicio DATE NOT NULL, data_prevista DATE NOT NULL,
 data_conclusao DATE, data_retirada DATE,
 status VARCHAR(13) NOT NULL CHECK(status IN ('PENDENTE','EM_EXECUCAO','CONCLUIDA','CANCELADA')),
 CONSTRAINT ck_mont_datas CHECK(data_prevista>=data_inicio AND
  (data_conclusao IS NULL OR data_conclusao>=data_inicio) AND
  (data_retirada IS NULL OR (data_conclusao IS NOT NULL AND data_retirada>=data_conclusao))),
 CONSTRAINT fk_mon_ped FOREIGN KEY(id_pedido) REFERENCES pedido(id_pedido) ON DELETE RESTRICT,
 CONSTRAINT fk_mon_func FOREIGN KEY(id_funcionario) REFERENCES funcionario(id_funcionario) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE troca (
 id_troca INT PRIMARY KEY, id_pedido INT NOT NULL,
 id_funcionario INT NOT NULL, data_troca DATE NOT NULL,
 motivo VARCHAR(160) NOT NULL, valor_cobrado DECIMAL(10,2) NULL CHECK(valor_cobrado>=0),
 status VARCHAR(12) NOT NULL CHECK(status IN ('ABERTA','CONCLUIDA','CANCELADA')),
 CONSTRAINT fk_tr_ped FOREIGN KEY(id_pedido) REFERENCES pedido(id_pedido) ON DELETE RESTRICT,
 CONSTRAINT fk_tr_func FOREIGN KEY(id_funcionario) REFERENCES funcionario(id_funcionario) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE item_troca (
 id_troca INT NOT NULL, id_produto INT NOT NULL,
 quantidade INT NOT NULL CHECK(quantidade>0),
 destino VARCHAR(16) NOT NULL CHECK(destino IN ('REAPROVEITADO','DESCARTADO','SUBSTITUIDO')),
 PRIMARY KEY(id_troca,id_produto),
 CONSTRAINT fk_it_tr FOREIGN KEY(id_troca) REFERENCES troca(id_troca) ON DELETE RESTRICT,
 CONSTRAINT fk_it_prod FOREIGN KEY(id_produto) REFERENCES produto(id_produto) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE movimentacao_estoque (
 id_movimento INT PRIMARY KEY, id_produto INT NOT NULL, data_movimento DATE NOT NULL,
 tipo VARCHAR(18) NOT NULL CHECK(tipo IN
  ('AJUSTE_ENTRADA','AJUSTE_SAIDA','ENTRADA_COMPRA','SAIDA_PEDIDO','ENTRADA_TROCA','SAIDA_TROCA')),
 quantidade INT NOT NULL CHECK(quantidade>0),
 id_compra INT NULL, id_pedido INT NULL, id_troca INT NULL,
 observacao VARCHAR(150),
 CONSTRAINT ck_mov_origem CHECK (
  (tipo IN ('AJUSTE_ENTRADA','AJUSTE_SAIDA') AND id_compra IS NULL AND id_pedido IS NULL AND id_troca IS NULL) OR
  (tipo='ENTRADA_COMPRA' AND id_compra IS NOT NULL AND id_pedido IS NULL AND id_troca IS NULL) OR
  (tipo='SAIDA_PEDIDO' AND id_compra IS NULL AND id_pedido IS NOT NULL AND id_troca IS NULL) OR
  (tipo IN ('ENTRADA_TROCA','SAIDA_TROCA') AND id_compra IS NULL AND id_pedido IS NULL AND id_troca IS NOT NULL)
 ),
 CONSTRAINT fk_mov_prod FOREIGN KEY(id_produto) REFERENCES produto(id_produto) ON DELETE RESTRICT,
 CONSTRAINT fk_mov_comp FOREIGN KEY(id_compra) REFERENCES compra(id_compra) ON DELETE RESTRICT,
 CONSTRAINT fk_mov_ped FOREIGN KEY(id_pedido) REFERENCES pedido(id_pedido) ON DELETE RESTRICT,
 CONSTRAINT fk_mov_tr FOREIGN KEY(id_troca) REFERENCES troca(id_troca) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE INDEX idx_at_data ON atendimento(data_atendimento);
CREATE INDEX idx_pedido_data ON pedido(data_pedido);
CREATE INDEX idx_mov_prod_data ON movimentacao_estoque(id_produto,data_movimento);
CREATE INDEX idx_troca_data ON troca(data_troca);

