-- JOIN de demonstração: pedido, cliente, atendimento, receita, itens e pagamentos
SELECT p.id_pedido, c.nome AS cliente_ficticio, a.data_atendimento, r.origem, p.status,
       COUNT(DISTINCT ip.id_produto) AS itens, COUNT(DISTINCT pg.id_pagamento) AS parcelas
FROM pedido p JOIN atendimento a ON a.id_atendimento=p.id_atendimento
 JOIN cliente c ON c.id_cliente=a.id_cliente
 JOIN receita r ON r.id_receita=p.id_receita
 LEFT JOIN item_pedido ip ON ip.id_pedido=p.id_pedido
 LEFT JOIN pagamento pg ON pg.id_pedido=p.id_pedido
GROUP BY p.id_pedido,c.nome,a.data_atendimento,r.origem,p.status LIMIT 10;

-- UPDATE e DELETE reais, confinados a transação revertida: sem adulterar a massa de exemplo.
START TRANSACTION;
INSERT INTO categoria (id_categoria,nome) VALUES (99,'TEMPORARIA_PARA_TESTE');
UPDATE categoria SET nome='TEMPORARIA_TESTADA' WHERE id_categoria=99;
DELETE FROM categoria WHERE id_categoria=99;
ROLLBACK;

-- G01 — Quantos atendimentos e pedidos por semana e qual conversão? Atende P1; KPI conversão.
SELECT YEARWEEK(a.data_atendimento,1) AS ano_semana,
 COUNT(DISTINCT a.id_atendimento) AS atendimentos,
 COUNT(DISTINCT p.id_pedido) AS pedidos,
 ROUND(100.0*COUNT(DISTINCT p.id_pedido)/NULLIF(COUNT(DISTINCT a.id_atendimento),0),2) AS taxa_conversao_pct
FROM atendimento a LEFT JOIN pedido p ON p.id_atendimento=a.id_atendimento
GROUP BY YEARWEEK(a.data_atendimento,1) ORDER BY ano_semana;

-- G02 — Qual o faturamento líquido mensal e ticket médio de pedidos concluídos? Atende P2; KPIs faturamento/ticket.
SELECT DATE_FORMAT(p.data_pedido,'%Y-%m') AS mes, COUNT(*) AS pedidos_concluidos,
 ROUND(SUM(v.total_itens-p.desconto),2) AS faturamento_estimado,
 ROUND(AVG(v.total_itens-p.desconto),2) AS ticket_medio
FROM pedido p JOIN (SELECT id_pedido,SUM(quantidade*preco_unitario) total_itens FROM item_pedido GROUP BY id_pedido) v USING(id_pedido)
WHERE p.status='CONCLUIDO' GROUP BY DATE_FORMAT(p.data_pedido,'%Y-%m') ORDER BY mes;

-- G03 — Quais pedidos têm saldo financeiro pendente? Atende P2; KPI saldo a receber.
SELECT p.id_pedido,p.status, ROUND(v.total_itens-p.desconto,2) AS valor_pedido,
 COALESCE(pg.total_pago,0) AS valor_pago,
 ROUND(v.total_itens-p.desconto-COALESCE(pg.total_pago,0),2) AS saldo_pendente
FROM pedido p JOIN (SELECT id_pedido,SUM(quantidade*preco_unitario) total_itens FROM item_pedido GROUP BY id_pedido) v USING(id_pedido)
LEFT JOIN (SELECT id_pedido,SUM(CASE WHEN status='QUITADO' THEN valor ELSE 0 END) total_pago FROM pagamento GROUP BY id_pedido) pg USING(id_pedido)
WHERE p.status='ABERTO' ORDER BY saldo_pendente DESC;

-- G04 — Quais produtos estão abaixo do estoque mínimo? Atende P3; KPI rupturas.
SELECT pr.sku,pr.descricao,pr.estoque_minimo,
 COALESCE(SUM(CASE WHEN m.tipo IN ('AJUSTE_ENTRADA','ENTRADA_COMPRA','ENTRADA_TROCA') THEN m.quantidade ELSE -m.quantidade END),0) AS saldo
FROM produto pr LEFT JOIN movimentacao_estoque m ON m.id_produto=pr.id_produto
GROUP BY pr.id_produto,pr.sku,pr.descricao,pr.estoque_minimo
HAVING saldo < pr.estoque_minimo ORDER BY saldo;

-- G05 — Quanto foi comprado por fornecedor nos pedidos recebidos? Atende P3; KPI compras.
SELECT f.nome AS fornecedor, COUNT(DISTINCT c.id_compra) AS compras_recebidas,
 ROUND(SUM(ic.quantidade*ic.custo_unitario),2) AS custo_total
FROM fornecedor f JOIN compra c ON c.id_fornecedor=f.id_fornecedor AND c.status='RECEBIDA'
JOIN item_compra ic ON ic.id_compra=c.id_compra
GROUP BY f.id_fornecedor,f.nome ORDER BY custo_total DESC;

-- G06 — Quais montagens estão pendentes ou atrasadas, sem usar a data corrente instável? Atende P4; KPI atraso.
SELECT m.id_montagem,m.id_pedido,m.status,m.data_prevista,
 DATEDIFF('2026-10-12',m.data_prevista) AS dias_atraso
FROM montagem m WHERE m.status IN ('PENDENTE','EM_EXECUCAO') AND m.data_prevista<'2026-10-12'
ORDER BY m.data_prevista;

-- G07 — Quais garantias de um ano permanecem vigentes (na data de referência)? Atende P4; KPI vigentes.
SELECT m.id_pedido,m.data_conclusao AS montagem_finalizada,
 DATE_ADD(m.data_conclusao,INTERVAL 1 YEAR) AS fim_garantia
FROM montagem m WHERE m.data_conclusao IS NOT NULL
AND '2026-10-12' BETWEEN m.data_conclusao AND DATE_ADD(m.data_conclusao,INTERVAL 1 YEAR)
ORDER BY fim_garantia LIMIT 30;

-- G08 — Que trocas ocorreram e qual o destino das peças? Atende P5; KPI reaproveitamento.
SELECT DATE_FORMAT(t.data_troca,'%Y-%m') AS mes, it.destino,
 COUNT(DISTINCT t.id_troca) AS trocas, SUM(it.quantidade) AS pecas
FROM troca t JOIN item_troca it ON it.id_troca=t.id_troca
WHERE t.status='CONCLUIDA' GROUP BY DATE_FORMAT(t.data_troca,'%Y-%m'),it.destino ORDER BY mes,it.destino;

-- G09 — Como se distribuem os recebimentos por forma? Atende P2; KPI recebimentos.
SELECT forma,COUNT(*) AS parcelas_recebidas,ROUND(SUM(valor),2) AS total
FROM pagamento WHERE status='QUITADO' GROUP BY forma ORDER BY total DESC;

-- G10 — Qual a taxa mensal de cancelamento de pedidos? Atende P1; KPI cancelamento.
SELECT DATE_FORMAT(data_pedido,'%Y-%m') AS mes,COUNT(*) total_pedidos,
 SUM(CASE WHEN status='CANCELADO' THEN 1 ELSE 0 END) cancelados,
 ROUND(100.0*SUM(CASE WHEN status='CANCELADO' THEN 1 ELSE 0 END)/COUNT(*),2) taxa_cancelamento_pct
FROM pedido GROUP BY DATE_FORMAT(data_pedido,'%Y-%m') ORDER BY mes;

-- A01 — Existe pedido sem atendimento? Verifica RN01.
SELECT p.id_pedido FROM pedido p LEFT JOIN atendimento a USING(id_atendimento) WHERE a.id_atendimento IS NULL;
-- A02 — Receita está associada a mais de um pedido ou atendimento diferente? Verifica RN02.
SELECT r.id_receita FROM receita r JOIN pedido p ON p.id_receita=r.id_receita WHERE r.id_atendimento<>p.id_atendimento;
-- A03 — Alguma receita externa tinha mais de um ano quando o pedido foi feito? Verifica RN03.
SELECT p.id_pedido,r.data_receita,p.data_pedido FROM pedido p JOIN receita r USING(id_receita)
WHERE r.origem='EXTERNA' AND (r.data_receita>p.data_pedido OR r.data_receita<DATE_SUB(p.data_pedido,INTERVAL 1 YEAR));
-- A04 — Falta armação ou lente para algum pedido? Verifica RN04.
SELECT p.id_pedido FROM pedido p LEFT JOIN item_pedido ip ON ip.id_pedido=p.id_pedido
 LEFT JOIN produto pr ON pr.id_produto=ip.id_produto
 GROUP BY p.id_pedido HAVING SUM(CASE WHEN pr.id_categoria=1 THEN 1 ELSE 0 END)=0
  OR SUM(CASE WHEN pr.id_categoria=2 THEN 1 ELSE 0 END)=0;
-- A05 — Há divergência entre valor e pagamentos dos pedidos concluídos? Verifica RN05.
SELECT p.id_pedido, ROUND(i.valor-p.desconto-COALESCE(pg.pago,0),2) diferenca
FROM pedido p JOIN (SELECT id_pedido,SUM(quantidade*preco_unitario) valor FROM item_pedido GROUP BY id_pedido) i USING(id_pedido)
LEFT JOIN (SELECT id_pedido,SUM(CASE WHEN status='QUITADO' THEN valor ELSE 0 END) pago FROM pagamento GROUP BY id_pedido) pg USING(id_pedido)
WHERE p.status='CONCLUIDO' AND ABS(i.valor-p.desconto-COALESCE(pg.pago,0))>0.009;
-- A06 — Existe compra não associada a pedido? Verifica RN06.
SELECT c.id_compra FROM compra c LEFT JOIN pedido p USING(id_pedido) WHERE p.id_pedido IS NULL;
-- A07 — Existe retirada sem montagem concluída ou anterior à conclusão? Verifica RN07.
SELECT id_montagem FROM montagem WHERE data_retirada IS NOT NULL AND
 (data_conclusao IS NULL OR data_retirada<data_conclusao);
-- A08 — Existe destino inválido declarado para peça trocada? Verifica RN08.
SELECT * FROM item_troca WHERE destino NOT IN ('REAPROVEITADO','DESCARTADO','SUBSTITUIDO');
-- A09 — Há saldo físico calculado negativo? Verifica RN09 (demanda validação transacional na aplicação).
SELECT id_produto,SUM(CASE WHEN tipo IN ('AJUSTE_ENTRADA','ENTRADA_COMPRA','ENTRADA_TROCA') THEN quantidade ELSE -quantidade END) saldo
FROM movimentacao_estoque GROUP BY id_produto HAVING saldo<0;
-- A10 — Pedido cancelado recebeu pagamento quitado? Verifica RN10.
SELECT p.id_pedido,pg.id_pagamento FROM pedido p JOIN pagamento pg USING(id_pedido)
WHERE p.status='CANCELADO' AND pg.status='QUITADO';
-- A11 — Estoque inclui entrada de compra que não está recebida? Verifica RN11.
SELECT m.id_movimento FROM movimentacao_estoque m JOIN compra c ON c.id_compra=m.id_compra
WHERE m.tipo='ENTRADA_COMPRA' AND c.status<>'RECEBIDA';
